import { getAssessmentCopy } from "@shared/assessmentLocalization";

const storageKey = (slug: string) => `piq-course-progress-${slug}`;
type LessonTimerState = { startedAt: number; completedAt?: number };
type SavedProgress = { lessons: string[]; quizScores: Record<string, number>; stageCount: number; lessonTimers: Record<string, LessonTimerState> };

const shuffle = <T,>(items: T[]) => { const copy = [...items]; for (let index = copy.length - 1; index > 0; index -= 1) { const swapIndex = Math.floor(Math.random() * (index + 1)); [copy[index], copy[swapIndex]] = [copy[swapIndex], copy[index]]; } return copy; };
const shuffleQuizForAttempt = (questions: CourseQuizQuestion[]) => shuffle(questions).map((question) => { const optionEntries = shuffle(question.options.map((option, index) => ({ option, index }))); return { ...question, options: optionEntries.map((entry) => entry.option), correctOption: optionEntries.findIndex((entry) => entry.index === question.correctOption) }; });

const readProgress = (course: CourseDefinition): SavedProgress => {
  try { const saved = JSON.parse(window.localStorage.getItem(storageKey(course.slug)) || "{}"); return { lessons: Array.isArray(saved.lessons) ? saved.lessons : [], quizScores: saved.quizScores && typeof saved.quizScores === "object" ? saved.quizScores : {}, stageCount: typeof saved.stageCount === "number" ? saved.stageCount : 0, lessonTimers: saved.lessonTimers && typeof saved.lessonTimers === "object" ? saved.lessonTimers : {} }; } catch { return { lessons: [], quizScores: {}, stageCount: 0, lessonTimers: {} }; }
};

export default function CourseWorkspace() {
  const [, params] = useRoute("/courses/:slug");
  const { locale } = useLocale();
  const baseCourse = courseCatalog.find((item) => item.slug === params?.slug);
  const course = useMemo(() => baseCourse ? localizeCourseDefinition(locale, baseCourse) : undefined, [baseCourse, locale]);
  if (!course) return <div className="min-h-screen bg-[#f7f3e8] p-8 text-[#16243d]"><p className="eyebrow text-[#a27e2e]">Course not found</p><Link href="/#courses" className="mt-5 inline-flex border-b border-[#16243d] pb-1 text-sm">Return to course catalog</Link></div>;
  return <CourseWorkspaceContent course={course} />;
}

function CourseWorkspaceContent({ course }: { course: CourseDefinition }) {
  const { user, isAuthenticated } = useAuth();
  const { t } = useLocale();
  const courseState = trpc.course.state.useQuery(undefined, { enabled: isAuthenticated });
  const paidStages = courseState.data?.find((item) => item.enrollment.courseSlug === course.slug)?.stages.filter((stage) => stage.paymentStatus === "paid").length ?? 0;
  const qaFixture = import.meta.env.DEV ? new URLSearchParams(window.location.search).get("qaEnrollment") : null;
  const fixturePaidStages = qaFixture === "pending" ? 0 : qaFixture === "stage1" ? 1 : qaFixture === "stage2" ? 2 : qaFixture === "stage3" ? 3 : qaFixture === "completed" ? 4 : null;
  const effectivePaidStages = fixturePaidStages ?? paidStages;
  const qualityControl = user?.role === "admin" || user?.email?.toLowerCase() === "profoundiqconsulting@gmail.com";
  if (!canAccessCourseLessons({ isAuthenticated, paidStages: effectivePaidStages, isQualityControlAdmin: qualityControl && !fixturePaidStages })) return <CourseAccessGate course={course} isAuthenticated={isAuthenticated} paidStages={effectivePaidStages} />;
  return <CourseWorkspaceUnlocked course={course} />;
}

function FirstStageCheckout({ course }: { course: CourseDefinition }) {
  const { user } = useAuth();
  const { t, locale } = useLocale();
  const enrollmentCopy = getCourseEnrollmentCopy(locale);
  const [name, setName] = useState(user?.name ?? "");
  const [email, setEmail] = useState(user?.email ?? "");
  const [consent, setConsent] = useState(false);
  const [mockOpen, setMockOpen] = useState(false);
  const enroll = trpc.course.enroll.useMutation({ onError: (error) => toast.error("Could not create enrollment", { description: error.message }) });
  const checkout = trpc.course.initializeStagePayment.useMutation({ onError: (error) => toast.error("Checkout could not be prepared", { description: error.message }) });
  const mockPayment = trpc.course.mockFirstStagePayment.useMutation({ onError: (error) => toast.error("Mock checkout failed", { description: error.message }) });
  const resetMockPayment = trpc.course.resetMockCoursePayments.useMutation({ onError: (error) => toast.error("Mock payment reset failed", { description: error.message }) });
  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!name.trim() || !email.trim() || !consent) return;
    enroll.mutate({ courseSlug: course.slug, name: name.trim(), email: email.trim(), consent: true }, { onSuccess: (result) => {
      if (!result.enrollmentId) { toast.error("Enrollment could not be created"); return; }
      checkout.mutate({ enrollmentId: result.enrollmentId, stage: 1 }, { onSuccess: (payment) => {
        if ("authorizationUrl" in payment && payment.authorizationUrl) window.location.href = payment.authorizationUrl;
        else if ("paid" in payment && payment.paid) window.location.reload();
        else toast.error("Paystack did not return a checkout link", { description: "Please try again shortly." });
      } });
    } });
  };
  const pending = enroll.isPending || checkout.isPending || mockPayment.isPending || resetMockPayment.isPending;
  const submitMock = () => {
    if (!name.trim() || !email.trim() || !consent) return;
    enroll.mutate({ courseSlug: course.slug, name: name.trim(), email: email.trim(), consent: true }, { onSuccess: (result) => {
      if (!result.enrollmentId) { toast.error("Enrollment could not be created"); return; }
      mockPayment.mutate({ enrollmentId: result.enrollmentId }, { onSuccess: () => { toast.success("Mock first payment completed", { description: "Module 1 access is now unlocked for this development session." }); setMockOpen(false); window.location.reload(); } });
    } });
  };
  return <form onSubmit={submit} className="mt-6 max-w-xl border border-white/15 bg-white/5 p-5 sm:p-6"><p className="text-xs font-black uppercase tracking-[.14em] text-[#c9a34e]">First step · unlock Module 1</p><p className="mt-2 text-sm leading-6 text-[#c1cad7]">Create or refresh your enrollment, then pay the first staged installment of <strong className="text-[#f7f3e8]">KES {(course.stageAmountsKes[0] ?? 0).toLocaleString()}</strong> through Paystack. Lesson access opens only after payment verification.</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><label className="grid gap-2 text-[10px] font-black uppercase tracking-[.12em] text-[#c1cad7]">{enrollmentCopy.yourName}<input required minLength={2} value={name} onChange={(event) => setName(event.target.value)} className="border border-white/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal text-[#16243d] outline-none focus:border-[#c9a34e]" /></label><label className="grid gap-2 text-[10px] font-black uppercase tracking-[.12em] text-[#c1cad7]">{enrollmentCopy.emailAddress}<input required type="email" value={email} onChange={(event) => setEmail(event.target.value)} className="border border-white/20 bg-[#f7f3e8] px-3 py-3 text-sm font-normal normal-case tracking-normal text-[#16243d] outline-none focus:border-[#c9a34e]" /></label></div><label className="mt-4 flex items-start gap-3 text-xs leading-5 text-[#c1cad7]"><input type="checkbox" required checked={consent} onChange={(event) => setConsent(event.target.checked)} className="mt-1 accent-[#c9a34e]" /> <span>I confirm these details may be used for enrollment, payment receipts, course access, certificates, and completion communications.</span></label><button type="submit" disabled={pending || !name.trim() || !email.trim() || !consent} className="mt-5 inline-flex items-center gap-2 bg-[#c9a34e] px-5 py-4 text-[10px] font-black uppercase tracking-[.15em] text-[#16243d] disabled:cursor-wait disabled:opacity-60">{pending ? <Loader2 size={14} className="animate-spin" aria-hidden="true" /> : <ArrowRight size={14} />}{pending ? enrollmentCopy.recording : `${enrollmentCopy.payment} · KES ${(course.stageAmountsKes[0] ?? 0).toLocaleString()}`}</button>{import.meta.env.DEV && <div className="mt-5 border-t border-dashed border-white/20 pt-5"><button type="button" onClick={() => setMockOpen((open) => !open)} className="text-[10px] font-black uppercase tracking-[.13em] text-[#c9a34e] underline underline-offset-4">{t("mockCheckout")}</button>{mockOpen && <div className="mt-3 border border-[#c9a34e]/50 bg-[#101d35] p-4"><p className="text-xs leading-5 text-[#c1cad7]">{t("mockCheckoutDescription")}</p><button type="button" onClick={submitMock} disabled={pending || !name.trim() || !email.trim() || !consent} className="mt-4 inline-flex items-center gap-2 border border-[#c9a34e] px-4 py-3 text-[10px] font-black uppercase tracking-[.13em] text-[#f7f3e8] disabled:opacity-60">{mockPayment.isPending || enroll.isPending ? <Loader2 size={13} className="animate-spin" aria-hidden="true" /> : null}{mockPayment.isPending || enroll.isPending ? "Simulating payment…" : t("simulatePayment")}</button>{window.location.pathname.includes("/courses/") && <button type="button" onClick={() => { const enrollmentId = Number(new URLSearchParams(window.location.search).get("enrollmentId")); if (!Number.isInteger(enrollmentId) || enrollmentId < 1) { toast.error("Open this course from an existing enrollment to reset mock payments"); return; } if (!window.confirm("Reset all mock payment stages for this enrollment?")) return; resetMockPayment.mutate({ enrollmentId }, { onSuccess: () => { toast.success("Mock payments reset", { description: "All staged payments are pending again for QA." }); window.location.reload(); } }); }} disabled={pending} className="mt-3 text-[10px] font-black uppercase tracking-[.12em] text-[#c1cad7] underline underline-offset-4 disabled:opacity-60">Reset mock payments</button>}</div>}</div>}</form>;
}

function CourseAccessGate({ course, isAuthenticated, paidStages }: { course: CourseDefinition; isAuthenticated: boolean; paidStages: number }) {
  const { t, locale } = useLocale();
  const authCopy = getAuthCopy(locale);
  return <div className="min-h-screen bg-[#f7f3e8] text-[#16243d]"><TransformationNav active="assessment" /><main className="container py-10 sm:py-16"><div className="mx-auto max-w-4xl"><Link href="/courses" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[.14em] text-[#7d5e1e]"><ArrowLeft size={14} /> {t("courses")}</Link><p className="eyebrow mt-10 text-[#a27e2e]">Course highlights · {course.duration}</p><h1 className="display mt-4 max-w-3xl text-5xl leading-[.95] tracking-[-.045em] sm:text-7xl">{course.title}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-[#4a566a]">{course.description}</p><CourseShareActions courseSlug={course.slug} courseTitle={course.title} /><div className="mt-10 grid gap-5 md:grid-cols-3"><div className="border border-[#16243d]/15 bg-white/55 p-5"><p className="eyebrow text-[#a27e2e]">For</p><p className="mt-3 text-sm leading-6">{course.audience}</p></div><div className="border border-[#16243d]/15 bg-white/55 p-5"><p className="eyebrow text-[#a27e2e]">Outcomes</p><p className="mt-3 text-sm leading-6">{course.outcomes.join(" · ")}</p></div><div className="border border-[#16243d]/15 bg-white/55 p-5"><p className="eyebrow text-[#a27e2e]">Investment</p><p className="mt-3 display text-2xl">KES {course.priceKes.toLocaleString()}</p><p className="mt-1 text-xs text-[#657084]">4 staged payments · KES {course.stageAmountsKes.map((amount) => amount.toLocaleString()).join(" / ")}</p></div></div><div className="mt-8 border-l-2 border-[#c9a34e] bg-[#16243d] p-6 text-[#f7f3e8] sm:p-8"><p className="eyebrow text-[#c9a34e]">Detailed lessons are protected</p><h2 className="display mt-3 text-3xl">{isAuthenticated ? "Unlock the learning workspace." : "Create your learner account to begin."}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#c1cad7]">{courseAccessReason({ isAuthenticated, paidStages, isQualityControlAdmin: false })}</p>{isAuthenticated ? <FirstStageCheckout course={course} /> : <div className="mt-6 flex flex-wrap gap-3"><Link href={`/auth?mode=login&returnTo=${encodeURIComponent(`/courses/${course.slug}`)}`} className="inline-flex items-center gap-2 bg-[#c9a34e] px-5 py-4 text-[10px] font-black uppercase tracking-[.15em] text-[#16243d]">{t("signInToContinue")} <ArrowRight size={14} /></Link><Link href={`/auth?mode=register&returnTo=${encodeURIComponent(`/courses/${course.slug}`)}`} className="inline-flex items-center gap-2 border border-[#c9a34e]/70 px-5 py-4 text-[10px] font-black uppercase tracking-[.15em] text-[#f7f3e8]">{authCopy.createAccount} <ArrowRight size={14} /></Link></div>}<div className="mt-4 flex flex-wrap gap-3">{isAuthenticated && <Link href="/dashboard" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[.15em] text-[#c1cad7] underline underline-offset-4 hover:text-[#c9a34e]">{t("myWorkspace")} <ArrowUpRight size={14} /></Link>}<Link href="/courses" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[.15em] text-[#c1cad7] underline underline-offset-4 hover:text-[#c9a34e]">{t("courses")} <ArrowUpRight size={14} /></Link></div></div></div></main></div>;
}

function CourseWorkspaceUnlocked({ course }: { course: CourseDefinition }) {
  const { t, locale } = useLocale();
  const enrollmentCopy = getCourseEnrollmentCopy(locale);
  const assessmentCopy = getAssessmentCopy(locale);
  const [progress, setProgress] = useState<SavedProgress>(() => readProgress(course));
  const { user, isAuthenticated } = useAuth();
  const courseState = trpc.course.state.useQuery(undefined, { enabled: isAuthenticated });
  const enrollMutation = trpc.course.enroll.useMutation({ onError: (error) => toast.error("Could not start enrollment", { description: error.message }) });
  const checkoutMutation = trpc.course.initializeStagePayment.useMutation({ onError: (error) => toast.error("Checkout could not be prepared", { description: "Your course access is unchanged. Please try again." }) });
  const updateIdentityMutation = trpc.course.updateEnrollmentIdentity.useMutation({ onSuccess: () => { setIdentityOpen(false); toast.success("Checkout details saved"); startCheckout(); }, onError: (error) => toast.error("Could not save checkout details", { description: error.message }) });
  const verifyMutation = trpc.course.verifyStagePayment.useMutation();
  const completeLessonMutation = trpc.course.completeLesson.useMutation();
  const submitQuizMutation = trpc.course.submitQuiz.useMutation();
  const requestCertificateMutation = trpc.course.requestCertificate.useMutation();
  const summarizeNotesMutation = trpc.dashboard.summarizeNotes.useMutation();
  const studyAidMutation = trpc.dashboard.generateStudyAid.useMutation();
  const currentEnrollment = courseState.data?.find((item) => item.enrollment.courseSlug === course.slug);
  const activePositionInput = useMemo(() => ({ enrollmentId: currentEnrollment?.enrollment.id ?? 0 }), [currentEnrollment?.enrollment.id]);
  const activePosition = trpc.course.activePosition.useQuery(activePositionInput, { enabled: Boolean(currentEnrollment?.enrollment.id) });
  const saveActivePositionMutation = trpc.course.saveActivePosition.useMutation();
  const [moduleIndex, setModuleIndex] = useState(0);
  const [quizOpen, setQuizOpen] = useState(false);
  const [quizOrder, setQuizOrder] = useState<CourseQuizQuestion[]>([]);
  const [quizAttemptNumber, setQuizAttemptNumber] = useState(0);
  const [quizResult, setQuizResult] = useState<{ score: number; correct: number; answers: Record<string, number> } | null>(null);
  const autoCertificateRequested = useRef(false);
  const serverPositionApplied = useRef(false);
  const [activeLessonId, setActiveLessonId] = useState<string | null>(null);
  const [simulationChoice, setSimulationChoice] = useState<number | null>(null);
  const [reflection, setReflection] = useState("");
  const [lessonStage, setLessonStage] = useState(0);
  const [timerNow, setTimerNow] = useState(() => Date.now());
  const [studyAid, setStudyAid] = useState<{ mode: "quiz" | "flashcards"; content: string } | null>(null);
  const [identityOpen, setIdentityOpen] = useState(false);
  const [identityConsent, setIdentityConsent] = useState(false);
  const [identityName, setIdentityName] = useState(user?.name ?? "");
  const [identityEmail, setIdentityEmail] = useState(user?.email ?? "");
  const [bookmarks, setBookmarks] = useState<string[]>(() => { try { const saved = JSON.parse(window.localStorage.getItem(`piq-course-bookmarks-${course.slug}`) || "[]"); return Array.isArray(saved) ? saved : []; } catch { return []; } });
  const [lessonNotes, setLessonNotes] = useState<Record<string, string>>(() => { try { const saved = JSON.parse(window.localStorage.getItem(`piq-course-notes-${course.slug}`) || "{}"); return saved && typeof saved === "object" ? saved : {}; } catch { return {}; } });
  const [selectedAnswers, setSelectedAnswers] = useState<Record<string, number>>({});
  const currentModule = course.modules[moduleIndex];
  const moduleBadges = useMemo(() => buildCourseModuleBadges({ modules: course.modules, completedLessonIds: progress.lessons, passedQuizModuleIds: Object.entries(progress.quizScores).filter(([, score]) => score >= COURSE_PASS_MARK).map(([moduleId]) => moduleId) }), [course.modules, progress.lessons, progress.quizScores]);
  const activeLesson = currentModule.lessons.find((lesson) => lesson.id === activeLessonId) ?? null;
  const lessonSecondsRemaining = (lessonId: string) => { if (progress.lessons.includes(lessonId)) return 0; const startedAt = progress.lessonTimers[lessonId]?.startedAt; return startedAt ? Math.max(0, 2400 - Math.floor((timerNow - startedAt) / 1000)) : 2400; };
  const activeLessonSecondsRemaining = activeLesson ? lessonSecondsRemaining(activeLesson.id) : 0;
  const activeLessonTimerComplete = Boolean(activeLesson && activeLessonSecondsRemaining <= 0);
  const activeLessonIndex = activeLesson ? currentModule.lessons.findIndex((lesson) => lesson.id === activeLesson.id) : -1;
  const nextLesson = activeLessonIndex >= 0 ? currentModule.lessons[activeLessonIndex + 1] ?? null : null;
  const continueToNextLesson = () => { if (!activeLessonTimerComplete) { toast.info("Keep studying before continuing", { description: `The next lesson unlocks when the 40-minute timer reaches zero. ${formatCountdown(activeLessonSecondsRemaining)} remaining.` }); return; } if (activeLesson && !progress.lessons.includes(activeLesson.id)) toggleLesson(activeLesson.id); if (nextLesson) openLesson(nextLesson.id); else setActiveLessonId(null); };
  const formatCountdown = (seconds: number) => `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`;
  const completedLessons = progress.lessons.length;
  const passedQuizzes = Object.values(progress.quizScores).filter((score) => score >= COURSE_PASS_MARK).length;
  const courseProgress = Math.round((completedLessons / (course.modules.length * 7)) * 70 + (passedQuizzes / course.modules.length) * 30);
  const isModuleReady = currentModule.lessons.every((lesson) => progress.lessons.includes(lesson.id));
  const isCourseComplete = passedQuizzes === course.modules.length && completedLessons === course.modules.length * 7;
  const badgeCelebrated = useRef(new Set(moduleBadges.filter((badge) => badge.status === "earned").map((badge) => badge.moduleId)));
  const persist = (next: SavedProgress) => { setProgress(next); window.localStorage.setItem(storageKey(course.slug), JSON.stringify(next)); };
  useEffect(() => { if (!activeLessonId || activeLessonTimerComplete) return; const interval = window.setInterval(() => setTimerNow(Date.now()), 1000); return () => window.clearInterval(interval); }, [activeLessonId, activeLessonTimerComplete]);
  useEffect(() => { if (!activeLesson || progress.lessons.includes(activeLesson.id) || progress.lessonTimers[activeLesson.id]) return; persist({ ...progress, lessonTimers: { ...progress.lessonTimers, [activeLesson.id]: { startedAt: Date.now() } } }); }, [activeLesson?.id, progress.lessons, progress.lessonTimers]);
  const openLesson = (lessonId: string) => { const lessonIndex = currentModule.lessons.findIndex((lesson) => lesson.id === lessonId); const previousLesson = lessonIndex > 0 ? currentModule.lessons[lessonIndex - 1] : null; if (previousLesson && !progress.lessons.includes(previousLesson.id)) { toast.info("Finish the previous lesson first", { description: "Lessons unlock in sequence after the previous 40-minute study block is complete." }); return; } setActiveLessonId(lessonId); setSimulationChoice(null); setReflection(""); setLessonStage(0); setTimerNow(Date.now()); };
  useEffect(() => { if (!activePosition.isSuccess || serverPositionApplied.current) return; if (activePosition.data) { setModuleIndex(Math.min(course.modules.length - 1, Math.max(0, activePosition.data.moduleIndex))); setActiveLessonId(activePosition.data.lessonId ?? null); } serverPositionApplied.current = true; }, [activePosition.data, activePosition.isSuccess, course.modules.length]);
  useEffect(() => { const enrollmentId = currentEnrollment?.enrollment.id; if (!enrollmentId || !serverPositionApplied.current) return; saveActivePositionMutation.mutate({ enrollmentId, moduleIndex, lessonId: activeLessonId }); }, [activeLessonId, currentEnrollment?.enrollment.id, moduleIndex]);
  const openQuiz = () => { setQuizOrder(shuffleQuizForAttempt(currentModule.quiz)); setQuizAttemptNumber((attempt) => attempt + 1); setQuizResult(null); setSelectedAnswers({}); setQuizOpen(true); };
  const toggleLesson = (lessonId: string) => { const isCompleting = !progress.lessons.includes(lessonId); if (isCompleting && lessonSecondsRemaining(lessonId) > 0) { toast.info("Lesson timer still running", { description: `Keep studying for ${formatCountdown(lessonSecondsRemaining(lessonId))} more.` }); return; } const lessons = isCompleting ? [...progress.lessons, lessonId] : progress.lessons.filter((id) => id !== lessonId); persist({ ...progress, lessons }); if (isCompleting) toast.success("Lesson complete", { description: "Your progress has been saved." }); if (isCompleting && currentEnrollment?.enrollment.id) completeLessonMutation.mutate({ enrollmentId: currentEnrollment.enrollment.id, lessonId }); };
  const submitQuiz = () => { const canonicalAnswers = Object.fromEntries(quizOrder.map((question) => { const selectedIndex = selectedAnswers[question.id]; const selectedOption = typeof selectedIndex === "number" ? question.options[selectedIndex] : undefined; const canonicalQuestion = currentModule.quiz.find((item) => item.id === question.id); return [question.id, canonicalQuestion?.options.indexOf(selectedOption ?? "") ?? -1]; })); const correct = currentModule.quiz.filter((question) => canonicalAnswers[question.id] === question.correctOption).length; const score = Math.round((correct / currentModule.quiz.length) * 100); persist({ ...progress, quizScores: { ...progress.quizScores, [currentModule.id]: score } }); if (currentEnrollment?.enrollment.id) submitQuizMutation.mutate({ enrollmentId: currentEnrollment.enrollment.id, moduleId: currentModule.id, answers: canonicalAnswers }); setQuizResult({ score, correct, answers: selectedAnswers }); toast.success(score >= COURSE_PASS_MARK ? "Quiz passed" : "Quiz submitted", { description: score >= COURSE_PASS_MARK ? "Review the explanations before continuing." : "Review the explanations and try again." }); };
  const stageUnlocked = (stage: number) => stage <= progress.stageCount + 1;
  useEffect(() => { const newlyEarned = moduleBadges.filter((badge) => badge.status === "earned" && !badgeCelebrated.current.has(badge.moduleId)); if (!newlyEarned.length) return; newlyEarned.forEach((badge) => { badgeCelebrated.current.add(badge.moduleId); toast.success(`Module ${badge.moduleIndex + 1} badge earned`, { description: "Seven lessons and the module quiz are complete. Keep building your learning streak." }); }); }, [moduleBadges]);
  useEffect(() => { const reference = new URLSearchParams(window.location.search).get("reference"); if (reference && isAuthenticated) verifyMutation.mutate({ reference }, { onSuccess: () => courseState.refetch() }); }, [isAuthenticated]);
  const startCheckout = () => { if (!isAuthenticated) { window.location.href = "/auth?returnTo=" + encodeURIComponent(window.location.pathname); return; } if (!currentEnrollment?.enrollment.id) { setIdentityName(user?.name ?? ""); setIdentityEmail(user?.email ?? ""); setIdentityConsent(false); setIdentityOpen(true); return; } const stage = currentEnrollment.stages.find((item) => item.paymentStatus !== "paid")?.stage ?? 1; checkoutMutation.mutate({ enrollmentId: currentEnrollment.enrollment.id, stage }, { onSuccess: (result) => { if ("authorizationUrl" in result && result.authorizationUrl) window.location.href = result.authorizationUrl; else toast.error("Paystack did not return a checkout link", { description: "Please try again shortly." }); } }); };
  const stageLabels = ["Enrollment / Module 1", "Module 4 access", "Module 7 access", "Certificate request"];
  const serverStageCount = currentEnrollment?.stages.filter((stage) => stage.paymentStatus === "paid").length ?? 0;
  const effectiveStageCount = Math.max(progress.stageCount, serverStageCount);
  const stageAmounts = useMemo(() => stageLabels.map((label, index) => ({ label, amount: course.stageAmountsKes[index] ?? course.stageAmountsKes[0] ?? 0, complete: effectiveStageCount > index })), [course.stageAmountsKes, effectiveStageCount]);
  const toggleBookmark = (key: string) => { const next = bookmarks.includes(key) ? bookmarks.filter((item) => item !== key) : [...bookmarks, key]; setBookmarks(next); window.localStorage.setItem(`piq-course-bookmarks-${course.slug}`, JSON.stringify(next)); };
  const updateLessonNote = (value: string) => { const next = { ...lessonNotes, [activeLessonId ?? ""]: value }; setLessonNotes(next); window.localStorage.setItem(`piq-course-notes-${course.slug}`, JSON.stringify(next)); };
  const summarizeNotes = async () => { const raw = (lessonNotes[activeLessonId ?? ""] ?? "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim(); if (!raw) { toast.error("Add a few notes first", { description: "The summary tool needs some lesson notes to work from." }); return; } try { const result = await summarizeNotesMutation.mutateAsync({ notes: raw }); toast.success("Notes summarized"); window.localStorage.setItem(`piq-course-summary-${course.slug}-${activeLessonId}`, result.summary); } catch (error) { toast.error("Could not summarize notes", { description: error instanceof Error ? error.message : "Please try again shortly." }); } };
  const generateStudyAid = async (mode: "quiz" | "flashcards") => { const raw = (lessonNotes[activeLessonId ?? ""] ?? "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim(); if (!raw) { toast.error("Add a few notes first"); return; } try { const result = await studyAidMutation.mutateAsync({ notes: raw, mode }); toast.success(mode === "quiz" ? "Practice quiz ready" : "Flashcards ready"); setStudyAid(result); window.localStorage.setItem(`piq-course-study-aid-${course.slug}-${activeLessonId}`, JSON.stringify(result)); } catch (error) { toast.error("Could not create study aid", { description: error instanceof Error ? error.message : "Please try again shortly." }); } };
  const exportLessonNotes = () => { if (!activeLesson) return; const content = `Profound IQ Consulting\n${course.title} · ${activeLesson.title}\n\n${(lessonNotes[activeLesson.id] || "No notes recorded.").replace(/<[^>]+>/g, "").replace(/&nbsp;/g, " ")}\n\nReflection\n${reflection || "No reflection recorded."}`; const url = URL.createObjectURL(new Blob([content], { type: "text/plain;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `${activeLesson.id}-notes.txt`; anchor.click(); URL.revokeObjectURL(url); };
  const requestCertificate = () => { if (!currentEnrollment?.enrollment.id) return; requestCertificateMutation.mutate({ enrollmentId: currentEnrollment.enrollment.id }, { onSuccess: (result) => { toast.success("Certificate ready", { description: "Your completion certificate was added to your dashboard and sent by email." }); if (result.fileUrl) window.open(result.fileUrl, "_blank", "noopener,noreferrer"); } }); };
  const shareCompletion = async () => { const url = `${window.location.origin}/dashboard?tab=courses`; const text = `I completed ${course.title} with Profound IQ Consulting.`; try { if (navigator.share) await navigator.share({ title: `${course.title} completion`, text, url }); else { const shareUrl = `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}`; window.open(shareUrl, "_blank", "noopener,noreferrer"); } } catch (error) { if ((error as DOMException).name !== "AbortError") toast.error("Could not share completion"); } };
  useEffect(() => { if (isCourseComplete && effectiveStageCount >= 4 && currentEnrollment?.enrollment.id && !autoCertificateRequested.current && !currentEnrollment.certificates?.length) { autoCertificateRequested.current = true; requestCertificate(); } }, [currentEnrollment, effectiveStageCount, isCourseComplete]);

  return <div className="min-h-screen bg-[#f7f3e8] text-[#16243d]"><TransformationNav active="assessment" /><main className="container py-10 sm:py-16"><div className="grid gap-10 lg:grid-cols-[1fr_300px]"><section><Link href="/#courses" className="inline-flex items-center gap-2 text-[10px] font-black uppercase tracking-[.14em] text-[#7d5e1e]"><ArrowLeft size={14} /> {t("courses")}</Link><p className="eyebrow mt-10 text-[#a27e2e]">{t("myWorkspace")} · {course.duration}</p><h1 className="display mt-4 max-w-3xl text-5xl leading-[.95] tracking-[-.045em] sm:text-7xl">{course.title}</h1><p className="mt-6 max-w-2xl text-lg leading-8 text-[#4a566a]">{course.description}</p><CourseShareActions courseSlug={course.slug} courseTitle={course.title} /><div className="mt-8 border-l-2 border-[#c9a34e] bg-white/60 p-5"><p className="text-xs font-black uppercase tracking-[.14em] text-[#7d5e1e]">Your learning signal</p><div className="mt-3 flex items-end justify-between gap-4"><p className="display text-4xl">{courseProgress}%</p><p className="text-right text-xs leading-5 text-[#657084]">{completedLessons} of 70 lessons<br />{passedQuizzes} of 10 quizzes passed</p></div><div className="mt-3 h-2 bg-[#16243d]/10"><div className="h-2 bg-[#c9a34e] transition-all" style={{ width: `${courseProgress}%` }} /></div></div><section className="mt-10 border border-[#c9a34e]/45 bg-[#fffaf0] p-5 sm:p-6"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="eyebrow text-[#a27e2e]">Your module milestones</p><h2 className="display mt-2 text-2xl">Earn a badge for each complete module.</h2></div><p className="text-xs text-[#657084]">Finish 7 lessons and pass the 15-question quiz.</p></div><div className="mt-5 grid gap-2 sm:grid-cols-2 lg:grid-cols-3">{moduleBadges.map((badge) => <ModuleCompletionBadge key={badge.moduleId} badge={badge} compact onSelect={() => setModuleIndex(badge.moduleIndex)} />)}</div></section><div className="mt-10 border border-[#16243d]/15 bg-white/55 p-5 sm:p-8"><div className="flex flex-wrap items-end justify-between gap-4 border-b border-[#16243d]/15 pb-5"><div><p className="eyebrow text-[#a27e2e]">Module {moduleIndex + 1} of {course.modules.length}</p><h2 className="display mt-2 text-3xl">{currentModule.title}</h2></div><span className="text-xs text-[#657084]">{currentModule.promise}</span></div><div className="mt-6 space-y-3">{currentModule.lessons.map((lesson, index) => <div key={lesson.id} role="button" tabIndex={0} onClick={() => openLesson(lesson.id)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); openLesson(lesson.id); } }} className={`cursor-pointer border p-4 transition hover:border-[#c9a34e] ${progress.lessons.includes(lesson.id) ? "border-[#c9a34e] bg-[#fffaf0]" : "border-[#16243d]/10 bg-[#f7f3e8]"}`}><label className="flex cursor-pointer items-start gap-3"><input type="checkbox" checked={progress.lessons.includes(lesson.id)} onChange={() => toggleLesson(lesson.id)} disabled={!progress.lessons.includes(lesson.id) && lessonSecondsRemaining(lesson.id) > 0} aria-label={`${lesson.title} ${progress.lessons.includes(lesson.id) ? "completed" : "completion"}`} className="mt-1 accent-[#a27e2e] disabled:cursor-not-allowed disabled:opacity-40" /><span><span className="block text-[10px] font-black uppercase tracking-[.12em] text-[#a27e2e]">Lesson {index + 1}</span><span className="mt-1 block text-sm font-bold">{lesson.title}</span><span className="mt-2 block text-xs leading-5 text-[#657084]">{lesson.summary} {lesson.outcome}</span></span></label></div>)}</div>{isModuleReady && <div className="mt-6 border-l-2 border-[#c9a34e] bg-[#16243d] p-5 text-[#f7f3e8]"><div className="flex items-start gap-3"><Sparkles size={18} className="mt-0.5 text-[#c9a34e]" /><div><p className="font-bold">Module quiz unlocked</p><p className="mt-1 text-sm leading-6 text-[#c1cad7]">Complete the 15-question quiz to lock in this module. You need {COURSE_PASS_MARK}% to pass and may retry without limit.</p><Button type="button" onClick={openQuiz} className="mt-4 bg-[#c9a34e] text-[#16243d]">{progress.quizScores[currentModule.id] !== undefined ? "Retake quiz" : "Start quiz"}</Button></div></div></div>}{progress.quizScores[currentModule.id] !== undefined && <p className={`mt-4 text-sm font-bold ${progress.quizScores[currentModule.id] >= COURSE_PASS_MARK ? "text-emerald-800" : "text-red-800"}`}>Latest quiz result: {progress.quizScores[currentModule.id]}% · {progress.quizScores[currentModule.id] >= COURSE_PASS_MARK ? "Passed" : "Retry available"}</p>}</div><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><Button type="button" variant="outline" onClick={() => setModuleIndex((index) => Math.max(0, index - 1))} disabled={moduleIndex === 0}><ArrowLeft size={15} /> {assessmentCopy.previousModule}</Button><span className="text-xs text-[#657084]">Progress saves automatically on this device.</span><Button type="button" onClick={() => setModuleIndex((index) => Math.min(course.modules.length - 1, index + 1))} disabled={!isModuleReady || progress.quizScores[currentModule.id] < COURSE_PASS_MARK || moduleIndex === course.modules.length - 1} className="bg-[#16243d] text-[#f7f3e8]">{assessmentCopy.nextModule} <ArrowRight size={15} /></Button></div></section><aside className="space-y-5"><div className="border border-[#16243d]/15 bg-[#16243d] p-5 text-[#f7f3e8]"><p className="eyebrow text-[#c9a34e]">{enrollmentCopy.payment}</p><p className="display mt-3 text-3xl">KES {course.priceKes.toLocaleString()}</p><p className="mt-2 text-sm leading-6 text-[#c1cad7]">Four staged payments of KES {course.stageAmountsKes.map((amount) => amount.toLocaleString()).join(" / ")} keep access aligned to your learning journey.</p><div className="mt-5 space-y-3">{stageAmounts.map((stage, index) => <div key={stage.label} className="flex items-center gap-3 text-xs"><span className={`grid h-6 w-6 place-items-center rounded-full border ${stage.complete ? "border-[#c9a34e] bg-[#c9a34e] text-[#16243d]" : "border-[#c1cad7]/40 text-[#c1cad7]"}`}>{stage.complete ? <CheckCircle2 size={14} /> : index + 1}</span><span className="flex-1 text-[#c1cad7]">{stage.label}</span><span className="font-bold text-[#c9a34e]">{stage.complete ? "Paid" : "25%"}</span></div>)}</div><Button type="button" onClick={startCheckout} disabled={enrollMutation.isPending || checkoutMutation.isPending || !stageUnlocked(Math.min(4, progress.stageCount + 1))} className="mt-6 w-full bg-[#c9a34e] text-[#16243d]">{checkoutMutation.isPending || enrollMutation.isPending ? "Preparing secure checkout…" : `Pay KES ${(course.stageAmountsKes[Math.min(3, progress.stageCount)] ?? course.stageAmountsKes[0] ?? 0).toLocaleString()} · stage ${Math.min(4, progress.stageCount + 1)} of 4`}</Button><p className="mt-3 text-[10px] leading-4 text-[#8f9db3]">Payment verification and stage unlocking are handled securely before access is granted.</p></div><div className="border-l-2 border-[#c9a34e] bg-white/60 p-5"><p className="eyebrow text-[#a27e2e]">{enrollmentCopy.certificate}</p><p className="mt-2 text-sm leading-6 text-[#657084]">After all modules and quizzes are passed, request your branded certificate. It will be emailed and remain available in your dashboard.</p><Button type="button" onClick={requestCertificate} disabled={!isCourseComplete || !currentEnrollment || requestCertificateMutation.isPending} className="mt-4 w-full bg-[#16243d] text-[#f7f3e8]"><LockKeyhole size={15} /> {requestCertificateMutation.isPending ? "Preparing certificate…" : isCourseComplete ? "Request certificate" : "Complete the course first"}</Button><Button type="button" variant="outline" onClick={shareCompletion} disabled={!isCourseComplete} className="mt-3 w-full">Share completion</Button></div><div className="border border-[#16243d]/10 bg-white/40 p-5"><p className="text-xs font-bold">Course outcomes</p>{course.outcomes.map((outcome) => <p key={outcome} className="mt-3 border-l border-[#c9a34e] pl-3 text-xs leading-5 text-[#657084]">{outcome}</p>)}</div></aside></div></main>{activeLesson && <div className="fixed inset-0 z-50 overflow-y-auto bg-[#071225]/80 p-4 sm:p-8"><div role="dialog" aria-modal="true" aria-labelledby="lesson-player-title" className="mx-auto max-w-4xl border border-[#c9a34e]/70 bg-[#f7f3e8] p-6 text-[#16243d] shadow-2xl sm:p-10"><div className="flex items-start justify-between gap-5 border-b border-[#16243d]/15 pb-6"><div><p className="eyebrow text-[#a27e2e]">Interactive lesson · {activeLesson.durationMinutes} minutes</p><h2 id="lesson-player-title" className="display mt-3 text-4xl">{activeLesson.title}</h2><p className="mt-3 max-w-2xl text-sm leading-6 text-[#657084]">{activeLesson.summary}</p></div><Button type="button" variant="outline" onClick={() => setActiveLessonId(null)} aria-label={enrollmentCopy.close + " lesson"}>{enrollmentCopy.close}</Button></div><div className="mt-6"><div className="border border-[#c9a34e]/60 bg-[#16243d] p-4 text-[#f7f3e8]"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#c9a34e]">{enrollmentCopy.details} · 40-minute study timer</p><p className="mt-1 text-xs leading-5 text-[#c1cad7]">{activeLessonTimerComplete ? "Time complete — the next lesson is unlocked." : "Stay in this lesson until the timer reaches zero."}</p></div><span role="timer" aria-live="polite" aria-label={activeLessonTimerComplete ? "Lesson timer complete" : `${formatCountdown(activeLessonSecondsRemaining)} remaining`} className="font-mono text-2xl font-bold text-[#c9a34e]">{activeLessonTimerComplete ? "00:00" : formatCountdown(activeLessonSecondsRemaining)}</span></div><div className="mt-3 h-2 overflow-hidden bg-white/15"><div className="h-full bg-[#c9a34e] transition-[width] duration-1000" style={{ width: `${Math.min(100, Math.round(((2400 - activeLessonSecondsRemaining) / 2400) * 100))}%` }} /></div></div><div className="mt-6"><div className="flex items-center justify-between gap-4"><div><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">Lesson progress</p><p className="mt-1 text-xs text-[#657084]">{lessonStage < 1 ? "Orienting" : lessonStage < 2 ? "Practising" : lessonStage < 3 ? "Reflecting" : "Ready to complete"} · approximately {Math.min(40, Math.round((lessonStage / 3) * 40))} of 40 minutes</p></div><span className="text-sm font-bold text-[#a27e2e]">{Math.round((lessonStage / 3) * 100)}%</span></div><div className="mt-3 h-2 overflow-hidden bg-[#16243d]/10"><div className="h-full bg-[#c9a34e] transition-all" style={{ width: `${Math.round((lessonStage / 3) * 100)}%` }} /></div></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_240px]"><div><div className="grid gap-3 sm:grid-cols-3">{activeLesson.objectives.map((objective) => <div key={objective} className="border-l-2 border-[#c9a34e] bg-white/60 p-3 text-xs leading-5 text-[#4a566a]">{objective}</div>)}</div><div className="mt-7 space-y-5">{activeLesson.sections.map((section, sectionIndex) => <article key={section.heading} className="border-t border-[#16243d]/15 pt-5"><div className="flex items-start justify-between gap-3"><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">{section.heading}</p><button type="button" onClick={() => toggleBookmark(`${activeLesson.id}:section:${sectionIndex}`)} className="text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e]">{bookmarks.includes(`${activeLesson.id}:section:${sectionIndex}`) ? "Saved" : "Save for later"}</button></div><p className="mt-2 text-sm leading-7 text-[#4a566a]">{section.body}</p>{section.callout && <p className="mt-3 border-l-2 border-[#c9a34e] bg-[#fffaf0] p-3 text-xs font-semibold leading-5 text-[#7d5e1e]">{section.callout}</p>}</article>)}</div><div className="mt-7 border border-[#c9a34e]/60 bg-[#16243d] p-5 text-[#f7f3e8]"><div className="flex items-start justify-between gap-3"><p className="eyebrow text-[#c9a34e]">Decision simulation</p><button type="button" onClick={() => toggleBookmark(`${activeLesson.id}:simulation`)} className="text-[10px] font-black uppercase tracking-[.1em] text-[#ead9ae]">{bookmarks.includes(`${activeLesson.id}:simulation`) ? "Saved" : "Save for later"}</button></div><p className="mt-2 text-sm leading-6 text-[#c1cad7]">{activeLesson.simulation.prompt}</p><div className="mt-4 grid gap-2">{activeLesson.simulation.options.map((option, index) => <button key={option} type="button" onClick={() => { setSimulationChoice(index); setLessonStage(2); }} className={`border p-3 text-left text-xs leading-5 ${simulationChoice === index ? "border-[#c9a34e] bg-[#c9a34e]/20" : "border-white/20 hover:border-[#c9a34e]"}`}>{option}</button>)}</div>{simulationChoice !== null && <p className="mt-4 text-xs leading-5 text-[#ead9ae]">{activeLesson.simulation.feedback[simulationChoice]}</p>}</div><div className="mt-6 border border-[#16243d]/15 bg-white/60 p-5"><p className="text-[10px] font-black uppercase tracking-[.14em] text-[#a27e2e]">Reflection prompt</p><p className="mt-2 text-sm leading-6 text-[#4a566a]">{activeLesson.reflectionPrompt}</p><div className="mt-4 flex flex-wrap gap-2 border border-[#16243d]/15 bg-[#f7f3e8] p-2"><button type="button" onClick={() => document.execCommand("bold")} className="border border-[#16243d]/20 px-3 py-1 text-xs font-bold">Bold</button><button type="button" onClick={() => document.execCommand("italic")} className="border border-[#16243d]/20 px-3 py-1 text-xs italic">Italic</button><button type="button" onClick={() => document.execCommand("insertUnorderedList")} className="border border-[#16243d]/20 px-3 py-1 text-xs">• Bullets</button><button type="button" onClick={() => void summarizeNotes()} disabled={summarizeNotesMutation.isPending} className="border border-[#a27e2e] px-3 py-1 text-xs font-bold text-[#7d5e1e]">{summarizeNotesMutation.isPending ? "Summarizing…" : "Summarize notes"}</button><button type="button" onClick={() => void generateStudyAid("quiz")} disabled={studyAidMutation.isPending} className="border border-[#16243d]/20 px-3 py-1 text-xs">{studyAidMutation.isPending ? "Creating…" : "Practice quiz"}</button><button type="button" onClick={() => void generateStudyAid("flashcards")} disabled={studyAidMutation.isPending} className="border border-[#16243d]/20 px-3 py-1 text-xs">Flashcards</button></div><div contentEditable suppressContentEditableWarning dangerouslySetInnerHTML={{ __html: lessonNotes[activeLesson.id] ?? "" }} onInput={(event) => { const value = event.currentTarget.innerHTML; updateLessonNote(value); setReflection(event.currentTarget.innerText); setLessonStage(3); }} data-placeholder="Write a brief field note for yourself…" className="mt-0 min-h-28 w-full border border-t-0 border-[#16243d]/20 bg-[#f7f3e8] p-3 text-sm outline-none empty:before:text-[#657084] empty:before:content-[attr(data-placeholder)] focus:border-[#c9a34e]" />{studyAid && <div className="mt-5 border-l-2 border-[#c9a34e] bg-[#fffaf0] p-4"><div className="flex items-center justify-between gap-3"><p className="text-[10px] font-black uppercase tracking-[.12em] text-[#7d5e1e]">AI {studyAid.mode === "quiz" ? "practice quiz" : "flashcards"}</p><button type="button" onClick={() => setStudyAid(null)} className="text-[10px] font-black uppercase tracking-[.1em] text-[#657084]">Close</button></div><p className="mt-3 whitespace-pre-wrap text-xs leading-6 text-[#4a566a]">{studyAid.content}</p></div>}</div></div><aside className="h-fit border border-[#c9a34e]/60 bg-[#101d35] p-5 text-[#f7f3e8]"><div className="grid h-40 place-items-center border border-[#c9a34e]/40 bg-gradient-to-br from-[#c9a34e]/30 via-[#2f6f78]/20 to-[#8b4f63]/30"><div className="text-center"><p className="text-[10px] font-black uppercase tracking-[.16em] text-[#c9a34e]">{activeLesson.illustration.label}</p><div className="mx-auto mt-4 h-14 w-14 rotate-45 border border-[#c9a34e]" /><p className="mt-4 text-xs text-[#c1cad7]">{activeLesson.illustration.caption}</p></div></div><p className="mt-4 text-xs leading-5 text-[#c1cad7]">Work in one uninterrupted 40-minute block: orient, practise, reflect, and record your next action.</p></aside></div><div className="mt-8 flex flex-wrap items-center justify-between gap-3 border-t border-[#16243d]/15 pt-6"><div className="flex flex-wrap items-center gap-2"><p className="text-xs text-[#657084]">Complete the lesson after reviewing the example, simulation, and reflection.</p><Button type="button" variant="outline" onClick={exportLessonNotes}><Download size={14} /> Export notes</Button></div><Button type="button" onClick={() => { if (!activeLessonTimerComplete) { toast.info("Lesson timer still running", { description: `The lesson must remain open for 40 minutes. ${formatCountdown(activeLessonSecondsRemaining)} remaining.` }); return; } toggleLesson(activeLesson.id); }} disabled={!activeLessonTimerComplete || progress.lessons.includes(activeLesson.id)} className="bg-[#16243d] text-[#f7f3e8]">{progress.lessons.includes(activeLesson.id) ? "Lesson complete" : activeLessonTimerComplete ? "Mark lesson complete" : `Complete in ${formatCountdown(activeLessonSecondsRemaining)}`}</Button><Button type="button" onClick={continueToNextLesson} disabled={!activeLessonTimerComplete} className="bg-[#c9a34e] text-[#16243d]">{nextLesson ? "Next lesson" : "Close lesson"} <ArrowRight size={15} /></Button></div></div></div></div>}{quizOpen && <div className="fixed inset-0 z-50 overflow-y-auto bg-[#071225]/80 p-4 sm:p-8"><div role="dialog" aria-modal="true" aria-labelledby="course-quiz-title" className="mx-auto max-w-3xl border border-[#c9a34e]/70 bg-[#f7f3e8] p-6 text-[#16243d] shadow-2xl sm:p-10"><div className="flex items-start justify-between gap-5"><div><p className="eyebrow text-[#a27e2e]">Module quiz · 15 questions</p><h2 id="course-quiz-title" className="display mt-3 text-4xl">Show your understanding.</h2><p className="mt-3 text-sm text-[#657084]">50% is the pass mark. You can repeat this quiz as many times as needed.</p><div role="status" className="mt-4 flex items-center gap-2 border border-[#c9a34e]/50 bg-[#ead9ae]/35 px-3 py-2 text-[10px] font-black uppercase tracking-[.1em] text-[#7d5e1e]"><Sparkles size={14} /> New randomized attempt · #{quizAttemptNumber}</div></div><Button type="button" variant="outline" onClick={() => setQuizOpen(false)} aria-label="Close quiz"><RotateCcw size={15} /></Button></div><div className="mt-8 space-y-6">{quizOrder.map((question, index) => <fieldset key={question.id} className="border-t border-[#16243d]/15 pt-5"><legend className="text-sm font-bold">{index + 1}. {question.prompt}</legend><p className="mt-1 text-[10px] uppercase tracking-[.12em] text-[#a27e2e]">Aligned lesson: {question.sourceLessonTitle}</p><div className="mt-3 grid gap-2">{question.options.map((option, optionIndex) => <label key={option} className={`flex cursor-pointer gap-3 border p-3 text-xs ${selectedAnswers[question.id] === optionIndex ? "border-[#c9a34e] bg-[#ead9ae]" : "border-[#16243d]/10"}`}><input type="radio" name={question.id} checked={selectedAnswers[question.id] === optionIndex} onChange={() => setSelectedAnswers({ ...selectedAnswers, [question.id]: optionIndex })} />{option}</label>)}</div></fieldset>)}</div>{quizResult && <section aria-live="polite" className="mt-8 border-t border-[#16243d]/15 pt-6"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="eyebrow text-[#a27e2e]">Learning review</p><h3 className="display mt-2 text-2xl">{quizResult.score}% · {quizResult.correct}/{currentModule.quiz.length} correct</h3><p className="mt-2 text-sm text-[#657084]">Read each explanation, then try another randomized attempt whenever you are ready.</p></div><Button type="button" onClick={openQuiz} className="bg-[#c9a34e] text-[#16243d]">New randomized attempt <RotateCcw size={14} /></Button></div><div className="mt-5 space-y-3">{quizOrder.map((question, index) => { const selectedIndex = quizResult.answers[question.id]; const selectedOption = typeof selectedIndex === "number" ? question.options[selectedIndex] : null; const isCorrect = selectedIndex === question.correctOption; const explanation = typeof selectedIndex === "number" ? question.optionExplanations[selectedIndex] : "No answer was selected; review the correct approach below."; return <article key={`feedback-${question.id}`} className={`border p-4 ${isCorrect ? "border-[#55705a]/45 bg-[#edf4ee]" : "border-[#8b4f63]/35 bg-[#fbf0f2]"}`}><div className="flex items-start gap-3"><span className="mt-0.5 text-xs font-black">{isCorrect ? "✓" : "!"}</span><div className="min-w-0"><p className="text-xs font-bold">{index + 1}. {question.prompt}</p><p className="mt-2 text-xs leading-5"><strong>{isCorrect ? "Correct response" : "Your response"}:</strong> {selectedOption ?? "Not answered"}</p>{!isCorrect && <p className="mt-1 text-xs leading-5"><strong>Correct answer:</strong> {question.options[question.correctOption]}</p>}<p className="mt-2 text-xs leading-5 text-[#4a566a]">{explanation}</p><p className="mt-2 border-t border-current/10 pt-2 text-xs leading-5 text-[#657084]">Lesson connection: {question.explanation}</p></div></div></article>; })}</div></section>}<Button type="button" onClick={submitQuiz} disabled={Boolean(quizResult) || Object.keys(selectedAnswers).length !== currentModule.quiz.length} className="mt-8 bg-[#16243d] text-[#f7f3e8]">{assessmentCopy.submitQuiz}</Button></div></div>}{identityOpen && <div className="fixed inset-0 z-50 grid place-items-center bg-[#071225]/80 p-4" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) setIdentityOpen(false); }}><div role="dialog" aria-modal="true" aria-labelledby="checkout-identity-title" className="w-full max-w-md border border-[#c9a34e]/70 bg-[#f7f3e8] p-6 text-[#16243d] shadow-2xl sm:p-8"><div className="flex items-start justify-between gap-4"><div><p className="eyebrow text-[#a27e2e]">{enrollmentCopy.payment} · {enrollmentCopy.details} 01</p><h2 id="checkout-identity-title" className="display mt-2 text-3xl">{enrollmentCopy.selectedCourse}</h2></div><button type="button" aria-label={enrollmentCopy.close + " checkout details"} onClick={() => setIdentityOpen(false)} className="text-xs font-black uppercase tracking-[.12em] text-[#657084]">Close</button></div><p className="mt-4 text-sm leading-6 text-[#4a566a]">These details will personalize your payment receipt, course certificate, and completion emails.</p><form onSubmit={(event) => { event.preventDefault(); if (!identityName.trim() || !identityEmail.trim() || !identityConsent) return; enrollMutation.mutate({ courseSlug: course.slug, name: identityName, email: identityEmail, consent: true }, { onSuccess: (result) => { setIdentityOpen(false); if (result.enrollmentId) checkoutMutation.mutate({ enrollmentId: result.enrollmentId, stage: 1 }, { onSuccess: (payment) => { if ("authorizationUrl" in payment && payment.authorizationUrl) window.location.href = payment.authorizationUrl; else toast.error("Paystack did not return a checkout link", { description: "Please try again shortly." }); } }); void courseState.refetch(); } }); }} className="mt-6 space-y-5"><label className="block text-xs font-black uppercase tracking-[.14em]">{enrollmentCopy.yourName}<input required minLength={2} value={identityName} onChange={(event) => setIdentityName(event.target.value)} autoComplete="name" className="mt-2 w-full border-b border-[#16243d]/30 bg-transparent py-3 text-base outline-none focus:border-[#c9a34e]" /></label><label className="block text-xs font-black uppercase tracking-[.14em]">{enrollmentCopy.emailAddress}<input required type="email" value={identityEmail} onChange={(event) => setIdentityEmail(event.target.value)} autoComplete="email" className="mt-2 w-full border-b border-[#16243d]/30 bg-transparent py-3 text-base outline-none focus:border-[#c9a34e]" /></label><p className="text-[11px] leading-5 text-[#657084]">Your email must be the address associated with this authenticated account so payment and course records stay together.</p><label className="flex items-start gap-3 text-[11px] leading-5 text-[#4a566a]"><input type="checkbox" checked={identityConsent} onChange={(event) => setIdentityConsent(event.target.checked)} className="mt-1 accent-[#a27e2e]" required /> <span>I consent to Profound IQ Consulting using these details to process this enrollment, payment receipt, course certificate, and completion emails.</span></label><Button type="submit" disabled={enrollMutation.isPending || checkoutMutation.isPending || !identityName.trim() || !identityEmail.trim() || !identityConsent} className="w-full bg-[#16243d] text-[#f7f3e8]">{enrollMutation.isPending || checkoutMutation.isPending ? enrollmentCopy.recording : enrollmentCopy.continueCheckout}<ArrowUpRight size={14} /></Button></form></div></div>}</div>;
}
